s16 MultiplyQ8(s16 num1, s16 num2)
{
    s32 product;
    s32 rounded;

    product = num1 * num2;
    rounded = product;
    if (rounded < 0)
    {
        rounded += 0xFF;
    }
    product = rounded >> 8;
    return product;
}

s16 DivideQ8(s16 num1, s16 num2)
{
    return (num1 << 8) / num2;
}

s16 ReciprocalQ8(s16 num1)
{
    s32 numerator = 0x10000;
    return (numerator / num1);
}

void InputHandler_Normal(void)
{
    s32 keyInput;

    keyInput = REG_KEYINPUT ^ KEYS_MASK;
    gNewKeys = keyInput & ~gHeldKeys;
    gHeldKeys = keyInput;

    if ((keyInput & RESET_KEYS) == RESET_KEYS)
    {
        SoftResetRom(RESET_ALL);
    }

    if (gHeldKeys & A_BUTTON)
    {
        gUnk_030034F0 += 1;
    }
    else
    {
        gUnk_030034F0 = 0;
    }
}

